<?php

declare(strict_types=1);

namespace App\Notifications;

use Illuminate\Notifications\Notification;

/**
 * In-app notification shown under the bell. Stored in the `notifications`
 * table only; e-mail is sent separately through TemplatedMail so members and
 * staff keep control of their e-mail preferences.
 *
 * `url` is always a path generated by route() on the server, never user input.
 */
class HubNotification extends Notification
{
    public function __construct(
        public readonly string $title,
        public readonly string $body,
        public readonly ?string $url = null,
        public readonly string $icon = 'bell',
        public readonly string $kind = 'general',
    ) {}

    /** @return list<string> */
    public function via(object $notifiable): array
    {
        return ['database'];
    }

    /** @return array<string, mixed> */
    public function toArray(object $notifiable): array
    {
        return [
            'title' => $this->title,
            'body' => $this->body,
            'url' => $this->url ? self::relative($this->url) : null,
            'icon' => $this->icon,
            'kind' => $this->kind,
        ];
    }

    /** Store paths, not absolute URLs, so links survive a domain change. */
    public static function relative(string $url): string
    {
        $path = parse_url($url, PHP_URL_PATH) ?: '/';
        $query = parse_url($url, PHP_URL_QUERY);

        return $path.($query ? '?'.$query : '');
    }
}
